def to_usize_rust(x):
    # Rust f64 as usize: trunc toward zero, saturate [0, MAX], NaN->0
    if math.isnan(x): return 0
    if x<=0: return 0
    if x>=2**64: return 2**64-1  # note f64 cast:values >=2^64 saturate; values between MAX and 2^64 (?) trunc to... 2^64-1024 representable etc Python int fine >MAX clamp
    return int(x)

