    v=float(vstr) if vstr not in ("inf","-inf","NaN") else (math.inf if vstr=="inf" else -math.inf if vstr=="-inf" else math.nan)
    for n in [1,2,3,5,10,25]:
        inp=b"a\n"*n
        exp,_,_=ref(inp,[f"--vertical-scale={vstr}"])
        # groups
        groups=0; last=None
        for y in range(n):
