            1
        }
    };
    std::process::exit(exit_code);
}

fn run(matches: clap::ArgMatches) -> io::Result<()> {
    if let Some(sub_matches) = matches.subcommand_matches("completion") {
        let shell = *sub_matches.get_one::<Shell>("shell").unwrap();
        let mut cmd = cli();
        let stdout = io::stdout();
        let mut handle = stdout.lock();
        // Hardcoded completions placeholders will be replaced / compared first
        clap_complete::generate(shell, &mut cmd, "code-minimap", &mut handle);
        return Ok(());
    }

    let hscale = *matches.get_one::<f64>("hscale").unwrap();
    let vscale = *matches.get_one::<f64>("vscale").unwrap();
    let padding = matches.get_one::<usize>("padding").copied();
    let encoding_raw = matches.get_one::<String>("encoding").unwrap().as_str();
    let encoding = match encoding_raw {
        _ if encoding_raw.eq_ignore_ascii_case("utf8") => InputEncoding::Utf8,
        _ => InputEncoding::Utf8Lossy,
    };
    let file = matches.get_one::<PathBuf>("file");

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    match file {
        Some(path) => {
            let f = File::open(path)?;
            let mut reader = BufReader::new(f);
            process(&mut reader, &mut out, hscale, vscale, padding, encoding)?;
        }
        None => {
            let stdin = io::stdin();
            let mut reader = stdin.lock();
            process(&mut reader, &mut out, hscale, vscale, padding, encoding)?;
        }
    };
    out.flush()?;
    Ok(())
}

#[derive(Clone, Copy, Debug)]
struct Interval {
    start: usize,
    end: usize, // exclusive, based on last byte index + 1
}

fn line_interval(line: &str) -> Option<Interval> {
    let mut first: Option<usize> = None;
    let mut last: Option<usize> = None;
    for (idx, ch) in line.char_indices() {
        if !ch.is_whitespace() {
            if first.is_none() {
                first = Some(idx);
            }
            last = Some(idx);
        }
    }
    match (first, last) {
        (Some(s), Some(l)) => Some(Interval { start: s, end: l + 1 }),
        _ => None,
    }
}

fn merge_into(current: &mut Option<Interval>, new_interval: Option<Interval>) {
    if let Some(n) = new_interval {
        match current {
            None => *current = Some(n),
            Some(cur) => {
                if n.start < cur.start { cur.start = n.start; }
                if n.end > cur.end { cur.end = n.end; }
            }
        }
    }
}

fn emit_chunk<W: Write>(
    out: &mut W,
    rows: &[Option<Interval>],
    hscale: f64,
    padding: Option<usize>,
) -> io::Result<()> {
    let chunk_max_end = rows.iter().filter_map(|r| r.map(|i| i.end)).fold(1usize, |a,b| a.max(b));
    let scaled_width = (chunk_max_end as f64 * hscale) as usize;
    let cells = scaled_width.div_ceil(2);
    let mut dots: Vec<u8> = vec![0; cells];
    const BITS: [[u8; 2]; 4] = [[0x01,0x08],[0x02,0x10],[0x04,0x20],[0x40,0x80]];
    for (dr, row) in rows.iter().enumerate() {
        if let Some(interval) = row {
            let sx = (interval.start as f64 * hscale) as usize;
            let ex = (interval.end as f64 * hscale) as usize;
            if ex > sx {
                // clipping: sx/ex should be within scaled_width for positive hscale.
                let end = ex.min(scaled_width);
                for x in sx..end {
                    dots[x/2] |= BITS[dr][x%2];
                }
            }
        }
    }
    let s: String = dots.iter().map(|&v| char::from_u32(0x2800 + v as u32).unwrap()).collect();
    match padding {
        Some(p) => writeln!(out, "{:<p$}", s, p=p),
        None => writeln!(out, "{}", s),
    }
}

fn process<R: BufRead, W: Write>(
    reader: &mut R,
    out: &mut W,
    hscale: f64,
    vscale: f64,
    padding: Option<usize>,
    encoding: InputEncoding,
) -> io::Result<()> {
    // line buffers
    let mut line_string = String::new();
    let mut line_bytes: Vec<u8> = Vec::new();

    let mut chunk_rows: Vec<Option<Interval>> = Vec::with_capacity(4);
    let mut current_row: Option<Interval> = None;
    let mut current_row_started = false;
    let mut y: usize = 0;

    loop {
        // Read one line according to encoding, mimicking BufRead::lines behavior
        let line_cow: Cow<'_, str>;
        let line_ref: &str;
        match encoding {
            InputEncoding::Utf8 => {
                line_string.clear();
                let n = reader.read_line(&mut line_string)?;
                if n == 0 {
                    break;
                }
                if line_string.ends_with('\n') {
                    line_string.pop();
                    if line_string.ends_with('\r') { line_string.pop(); }
                }
                line_cow = Cow::Borrowed("");
                line_ref = &line_string;
                // Use line_ref below (line_cow unused)
                let _ = &line_cow;
                handle_line(line_ref, y, vscale, hscale, padding, out, &mut chunk_rows, &mut current_row, &mut current_row_started)?;
            }
            InputEncoding::Utf8Lossy => {
                line_bytes.clear();
                let n = reader.read_until(b'\n', &mut line_bytes)?;
                if n == 0 {
                    break;
                }
                if line_bytes.ends_with(b"\n") {
                    line_bytes.pop();
                    if line_bytes.ends_with(b"\r") { line_bytes.pop(); }
                }
                let cow = String::from_utf8_lossy(&line_bytes);
                // Need to handle before cow drops
                handle_line(&cow, y, vscale, hscale, padding, out, &mut chunk_rows, &mut current_row, &mut current_row_started)?;
            }
        }
        y = y.wrapping_add(1);
    }

    // EOF: finalize current row if started
    if current_row_started {
        chunk_rows.push(current_row);
    }
    if !chunk_rows.is_empty() {
        emit_chunk(out, &chunk_rows, hscale, padding)?;
    }
    Ok(())
}

fn handle_line<W: Write>(
    line: &str,
    y: usize,
    vscale: f64,
    hscale: f64,
    padding: Option<usize>,
    out: &mut W,
    chunk_rows: &mut Vec<Option<Interval>>,
    current_row: &mut Option<Interval>,
    current_row_started: &mut bool,
) -> io::Result<()> {
    *current_row_started = true;
    let interval = line_interval(line);
    merge_into(current_row, interval);
    let cur_key = (y as f64 * vscale) as usize;
    let next_key = ((y.wrapping_add(1)) as f64 * vscale) as usize;
    if next_key != cur_key {
        chunk_rows.push(*current_row);
        *current_row = None;
        *current_row_started = false;
        if chunk_rows.len() == 4 {
            emit_chunk(out, chunk_rows, hscale, padding)?;
            chunk_rows.clear();
        }
    }
    Ok(())
}
RS
