    reader: &mut R,
    out: &mut W,
    hscale: f64,
    vscale: f64,
    padding: Option<usize>,
    encoding: InputEncoding,
) -> io::Result<()> {
    let mut line_string = String::new();
    let mut line_bytes: Vec<u8> = Vec::new();

    let mut chunk_rows: Vec<Option<Interval>> = Vec::with_capacity(4);
    let mut current_row: Option<Interval> = None;
    let mut current_row_started = false;
    let mut pending: VecDeque<(usize, Vec<Option<Interval>>)> = VecDeque::new();
    let mut y: usize = 0;

    loop {
        // Read one line. On error, flush complete pending chunks first; a write
        // error while doing so takes precedence over the read error.
        let read_result: io::Result<usize>;
        let is_utf8 = matches!(encoding, InputEncoding::Utf8);
        if is_utf8 {
            line_string.clear();
            read_result = reader.read_line(&mut line_string);
        } else {
            line_bytes.clear();
            read_result = reader.read_until(b'\n', &mut line_bytes);
        }
        let n = match read_result {
            Ok(n) => n,
            Err(read_err) => {
                while let Some((_, rows)) = pending.pop_front() {
                    emit_chunk(out, &rows, hscale, padding)?;
                }
                return Err(read_err);
            }
        };
        if n == 0 {
            break;
        }

        if is_utf8 {
            if line_string.ends_with('\n') {
                line_string.pop();
                if line_string.ends_with('\r') {
                    line_string.pop();
                }
            }
            handle_line(
                &line_string,
                y,
                vscale,
                &mut chunk_rows,
                &mut current_row,
                &mut current_row_started,
                &mut pending,
            );
        } else {
            if line_bytes.ends_with(b"\n") {
                line_bytes.pop();
                if line_bytes.ends_with(b"\r") {
                    line_bytes.pop();
                }
            }
            let cow = String::from_utf8_lossy(&line_bytes);
            handle_line(
                &cow,
                y,
                vscale,
                &mut chunk_rows,
                &mut current_row,
                &mut current_row_started,
                &mut pending,
            );
        }

        // Release pending chunks two input lines after they were completed.
        while let Some((release_y, _)) = pending.front() {
            if *release_y <= y {
                let (_, rows) = pending.pop_front().unwrap();
                emit_chunk(out, &rows, hscale, padding)?;
            } else {
                break;
            }
        }
        y = y.wrapping_add(1);
    }

    if current_row_started {
        chunk_rows.push(current_row);
    }
    if !chunk_rows.is_empty() {
        pending.push_back((usize::MAX, std::mem::take(&mut chunk_rows)));
    }
    while let Some((_, rows)) = pending.pop_front() {
        emit_chunk(out, &rows, hscale, padding)?;
    }
    Ok(())
}

fn handle_line(
    line: &str,
    y: usize,
    vscale: f64,
    chunk_rows: &mut Vec<Option<Interval>>,
    current_row: &mut Option<Interval>,
    current_row_started: &mut bool,
    pending: &mut VecDeque<(usize, Vec<Option<Interval>>)>,
) {
    *current_row_started = true;
    let interval = line_interval(line);
    merge_into(current_row, interval);
    let cur_key = (y as f64 * vscale) as usize;
    let next_key = (y.wrapping_add(1) as f64 * vscale) as usize;
    if next_key != cur_key {
        chunk_rows.push(*current_row);
        *current_row = None;
        *current_row_started = false;
        if chunk_rows.len() == 4 {
            let rows = std::mem::take(chunk_rows);
            pending.push_back((y.wrapping_add(2), rows));
        }
    }
}
